'use strict';
// Auth tokens stay in memory. Database policies, not this screen, enforce ownership.
const cfg=window.GREYLAD_CONFIG||{};
const base=(cfg.supabaseUrl||'').replace(/\/$/,'');
const key=cfg.supabasePublishableKey||'';
const q=s=>document.querySelector(s);
let token=null;let rows=[];let expiry=0;
const form=q('#editor');
function message(text,error=false){const el=q('#message');el.hidden=false;el.textContent=text;el.classList.toggle('error',error);}
function signOut(){token=null;expiry=0;rows=[];form.reset();form.elements.id.value='';q('#saved').replaceChildren();q('#studio').hidden=true;q('#login').hidden=false;}
async function request(path,options={}){
 if(token&&Date.now()>=expiry){signOut();throw Error('Your session expired. Please sign in again.');}
 const response=await fetch(base+path,{...options,headers:{apikey:key,...(token?{Authorization:'Bearer '+token}:{}),...options.headers}});
 if(!response.ok){if(response.status===401&&token)signOut();throw Error(response.status===401?'Sign-in failed or your session expired. Check your details and try again.':response.status===403?'Your account is not allowed to make this change.':'The request failed ('+response.status+'). Check the backend setup and try again.');}
 if(response.status===204)return null;const text=await response.text();return text?JSON.parse(text):null;
}
function busy(target,state){for(const b of target.querySelectorAll('button'))b.disabled=state;}
if(!base||!key){q('#setup').hidden=false;}else{q('#login').hidden=false;}
q('#login').addEventListener('submit',async e=>{e.preventDefault();busy(e.target,true);try{const values=new FormData(e.target);const data=await request('/auth/v1/token?grant_type=password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:values.get('email'),password:values.get('password')})});token=data.access_token;expiry=Date.now()+data.expires_in*1000;const owners=await request('/rest/v1/greylad_owners?select=user_id');if(!owners.length){signOut();throw Error('This account is not approved as the Greylad owner.');}e.target.reset();q('#login').hidden=true;q('#studio').hidden=false;message('Signed in. Drafts are visible only to you.');await loadRows();}catch(err){if(token)signOut();message(err.message,true);}finally{busy(e.target,false);}});
q('#logout').addEventListener('click',async()=>{try{await request('/auth/v1/logout',{method:'POST'});}catch{}finally{signOut();message('Signed out.');}});
q('#reset').addEventListener('click',()=>{form.reset();form.elements.id.value='';message('Ready for a new entry.');});
async function loadRows(){rows=await request('/rest/v1/greylad_entries?select=*&order=created_at.desc');const target=q('#saved');target.replaceChildren();if(!rows.length){target.textContent='No saved entries yet. Create your first note above.';return;}for(const row of rows){const article=document.createElement('article');const info=document.createElement('div');const title=document.createElement('strong');title.textContent=row.title;const status=document.createElement('p');status.className='small';status.textContent=row.category+' · '+(row.published?'Published':'Draft');info.append(title,status);const edit=document.createElement('button');edit.textContent='Edit';edit.addEventListener('click',()=>{form.reset();for(const name of ['id','title','category','summary','body','status','resource_url'])form.elements[name].value=row[name]||'';form.elements.published.checked=row.published;form.scrollIntoView({behavior:'smooth'});});const remove=document.createElement('button');remove.textContent='Delete';remove.addEventListener('click',async()=>{if(!confirm('Delete “'+row.title+'”? This removes the entry. Any attached file remains in storage until removed separately.'))return;remove.disabled=true;try{const deleted=await request('/rest/v1/greylad_entries?id=eq.'+encodeURIComponent(row.id),{method:'DELETE',headers:{Prefer:'return=representation'}});if(!deleted||deleted.length!==1)throw Error('No entry was deleted. Your access may have changed.');if(form.elements.id.value===row.id){form.reset();form.elements.id.value='';}await loadRows();message('Entry deleted.');}catch(err){message(err.message,true);remove.disabled=false;}});article.append(info,edit,remove);target.append(article);}}
form.addEventListener('submit',async e=>{e.preventDefault();busy(form,true);let uploaded=false;let saved=false;try{const f=new FormData(form);let url=String(f.get('resource_url')||'').trim();if(url&&!/^https?:\/\//i.test(url))throw Error('Use an http:// or https:// resource link.');const file=f.get('file');if(file&&file.size){if(file.size>10*1024*1024)throw Error('Please choose a file smaller than 10 MB.');const ext=file.name.split('.').pop().toLowerCase();const types={pdf:'application/pdf',csv:'text/csv',txt:'text/plain',png:'image/png',jpg:'image/jpeg',jpeg:'image/jpeg',webp:'image/webp',docx:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'};if(!types[ext])throw Error('This file format is not supported.');const name=crypto.randomUUID()+'.'+ext;await request('/storage/v1/object/greylad-public/'+name,{method:'POST',headers:{'Content-Type':types[ext]},body:file});url=base+'/storage/v1/object/public/greylad-public/'+name;uploaded=true;form.elements.resource_url.value=url;form.elements.file.value='';}
 const payload={title:String(f.get('title')).trim(),category:f.get('category'),summary:String(f.get('summary')).trim(),body:String(f.get('body')).trim(),status:String(f.get('status')).trim(),resource_url:url||null,published:f.get('published')==='on'};if(!payload.title||!payload.summary||!payload.body)throw Error('Title, summary and full note cannot be blank.');const id=f.get('id');const result=await request('/rest/v1/greylad_entries'+(id?'?id=eq.'+encodeURIComponent(id):''),{method:id?'PATCH':'POST',headers:{'Content-Type':'application/json',Prefer:'return=representation'},body:JSON.stringify(payload)});if(!result||result.length!==1)throw Error('No entry was saved. Your access may have changed.');saved=true;form.reset();form.elements.id.value='';await loadRows();message(payload.published?'Published. Your entry is now available on the website.':'Draft saved. Only the owner can read it.');}catch(err){message((saved?'Entry saved, but refreshing the list failed. ':uploaded?'File uploaded; entry not saved. The resource link has been retained so you can retry. ':'')+err.message,true);}finally{busy(form,false);}});
